import { addDays } from 'date-fns'
import React, { useRef } from 'react'
import Button from '../Button/Button'
import { useLocale } from '../contexts/LocaleContext'
import type { DatePickerProps } from './DatePicker'
import DatePicker, { Modes } from './DatePicker'

const modes = {
  'Modes.Day': Modes.Day,
  'Modes.Week': Modes.Week,
  'Modes.Range': Modes.Range,
}

export default {
  title: 'Components/DatePicker',
  component: DatePicker,
  argTypes: {
    initialDate: {
      control: 'date',
    },
    mode: {
      control: { type: 'select' },
      options: Object.keys(modes),
      mapping: modes,
    },
    initialTimezone: {
      control: {
        type: 'select',
      },
      options: ['America/Regina', 'UTC', 'Asia/Tokyo'],
    },
  },
  args: {
    initialDate: new Date().toISOString().split('T')[0],
    mode: Modes.Day,
  },
}

function Template(args: DatePickerProps): JSX.Element {
  const clearRef = useRef<HTMLButtonElement | null>(null)
  const [, setLocale] = useLocale()

  const mode = args.mode

  const date = new Date((args.initialDate as unknown) as number)
  const initialDate = (mode === Modes.Range
    ? [date, addDays(date as Date, 10)]
    : date) as Date | [Date, Date]

  return (
    <div className="m-6 space-y-4">
      <DatePicker
        {...args}
        clearRef={clearRef}
        initialDate={initialDate}
        mode={mode}
      />
      <Button onClick={() => clearRef.current?.click()}>Clear</Button>
      <div className="flex space-x-4">
        <Button onClick={() => setLocale('en')}>English</Button>
        <Button onClick={() => setLocale('fr')}>French</Button>
        <Button onClick={() => setLocale('es')}>Spanish</Button>
      </div>
    </div>
  )
}

export const Default = {
  render: Template,
}
